_APP_TITLES = {   # app_id: (uz, ru, en)
    "chrome": ("Google Chrome",) * 3, "browser": ("Brauzer", "Браузер", "Browser"), "new_window": ("Yangi brauzer oynasi", "Новое окно браузера", "New browser window"),
    "downloads": ("Downloads papkasi", "Папка Downloads", "Downloads folder"), "desktop": ("Desktop papkasi", "Рабочий стол", "Desktop folder"),
    "documents": ("Documents papkasi", "Папка Documents", "Documents folder"), "calculator": ("Kalkulyator", "Калькулятор", "Calculator"),
    "notepad": ("Notepad",) * 3, "explorer": ("Fayl menejeri", "Проводник", "File Explorer"), "youtube": ("YouTube",) * 3,
    "search": ("Google'da qidiruv", "Поиск в Google", "Google search"),
    "winsettings": ("Windows Sozlamalari", "Параметры Windows", "Windows Settings"),
    "vscode": ("Visual Studio Code",) * 3, "music": ("Music papkasi", "Папка Music", "Music folder"),
    "pictures": ("Pictures papkasi", "Папка Pictures", "Pictures folder"), "videos": ("Videos papkasi", "Папка Videos", "Videos folder"),
}
_IDX = {"uz": 0, "ru": 1, "en": 2}
from .i18n_voice import S as _VOICE_S  # noqa: E402
_S.update(_VOICE_S)


def T(key: str, lang: str = "uz", **kw) -> str:
    entry = _S.get(key)
    if entry is None:
        return key
    s = entry[_IDX.get(lang, 0)]
    try:
        return s.format(**kw) if kw else s
    except (KeyError, IndexError, ValueError):
        return s


def has(key: str) -> bool:
    return key in _S


def app_title(app_id: str, lang: str = "uz") -> str:
    t = _APP_TITLES.get(app_id)
    return t[_IDX.get(lang, 0)] if t else app_id
